class Tx(TypedDict):
  """One L2 transaction, as listed by `txs`, `accountTxs` and `blockTxs`."""

  hash: str
  """Transaction hash (hex). L1 priority and internal transactions carry a synthetic, zero-padded hash."""
  type: int
  """Transaction type (`tx_type`): 1-7, 30-32, 37 and 38 are L1 priority operations (1 = deposit); 8-20, 28, 29, 35, 36, 41 and 42 are user L2 transactions (8 change pub key, 9 create sub-account, 12 transfer, 14 create order, 15 cancel order, 20 update leverage, ...); 21-27 are internal sequencer operations (claim, cancel, deleverage, exit, cancel-all, liquidate, create order). Observed live as `0` for an L2ApproveIntegrator (type 45) transaction."""
  info: str
  """The transaction itself, JSON-encoded: the Go `L2*TxInfo` struct of its type (e.g. `AccountIndex`, `MarketIndex`, `Nonce`, `Sig`), as signed."""
  event_info: str
  """What executing the transaction did, JSON-encoded with compact keys (e.g. a trade `t`, the maker order `mo` and taker order `to` of a fill); empty for some types."""
  status: Literal[0, 1, 2, 3]
  """Transaction status: `0` failed, `1` pending (queued, not yet executed), `2` executed, `3` final: executed and settled, no longer changing (the venue's docs call it "Pending - Final State")."""
  transaction_index: int
  """Position of the transaction within its block."""
  l1_address: str
  """L1 address of the account that sent the transaction."""
  account_index: int
  """Account that sent the transaction."""
  nonce: int
  """Nonce of the signing API key; `-1` for L1 priority and internal transactions. Some clients use timestamps as nonces with skip-nonce."""
  expire_at: int
  """When the sequencer stops accepting the transaction, in epoch milliseconds (`ExpiredAt`); `9223372036854775807` (int64 max) for L1 priority and internal transactions that never expire, so it is kept a plain integer."""
  block_height: int
  """Height of the block that includes the transaction."""
  queued_at: TimestampMillis
  """When the sequencer queued the transaction."""
  executed_at: TimestampMillis
  """When the transaction was executed."""
  sequence_index: int
  """Global, strictly increasing (but sparse) sequence number of the transaction; `txs`/`accountTxs` paginate on it."""
  parent_hash: str
  """Hash of the transaction that triggered this one (internal transactions such as a fill claim or a triggered cancel); empty otherwise."""
  api_key_index: int
  """API key that signed the transaction; `0` for deposits and `255` for internal transactions."""
  transaction_time: TimestampMicros
  """When the transaction was processed."""


