  """Requested base amount as an integer string, or `""` when the RFQ was sized by the other amount."""
  quote_amount: int | Literal['']
  """Requested quote amount as an integer string, or `""` when the RFQ was sized by the other amount."""
  status: Literal['opened', 'order_created', 'closed']
  """Lifecycle state: open for responses, an order was created from it, or closed."""
  metadata: RFQMetadata
  """Pricing context the venue attaches to the RFQ."""
  responses: list[RFQResponseEntry]
