class ExplorerLog(TypedDict):
  """One log (an executed transaction that produced public data)."""

  tx_type: str
  """Transaction type (`L2CreateOrder`, `InternalClaimOrder`, `L1Deposit`, ...). The documented set is incomplete (it lacks `InternalLiquidateSpot`, which the venue sends), so it stays a string."""
  hash: str
  """Transaction hash (hex, no `0x`)."""
  time: TimestampIso
  """When the transaction executed."""
  pubdata: ExplorerPubData
  """Decoded public data of the log."""
  pubdata_type: Literal[
    'Empty',
    'L1Deposit',
    'L1CreateMarket',
    'L1UpdateMarket',
    'L2CreateSubAccount',
    'L2CreatePublicPool',
    'L2UpdatePublicPool',
    'L2MintShares',
    'L2UpdateLeverage',
    'L2UpdateMargin',
    'L2Transfer',
    'Withdraw',
    'Trade',
    'TradeWithFunding',
    'LiquidationTrade',
    'LiquidationTradeWithFunding',
    'BurnedShares',
    'ExitPosition',
    'ExitPositionWithFunding',
    'Deleverage',
    'DeleverageWithFunding',
    'L1RegisterAsset',
    'L1UpdateAsset',
    'L1CreateSpotMarket',
    'L1UpdateSpotMarket',
    'WithdrawV2',
    'L1CreateMarketV2',
    'L1DepositV2',
    'L1UpdateMarketV2',
    'L2TransferV2',
    'L2CreateStakingPool',
    'L2UpdateStakingPool',
    'L2StakeAssets',
    'UnstakeAssets',
    'L1SetSystemConfig',
    'ExecutedPendingUnlock',
    'L2UpdateAccountConfig',
    'L2UpdateMarketConfig',
  ]
  """Kind of public data the log carries; names the one `pubdata` key present."""
  status: Literal['nothing_to_execute', 'committed', 'verified', 'executed'] | None
  """L1 status of the batch holding the log; `null` until the log's block is in a batch that reached L1."""


