class ExplorerBlock(TypedDict):
  """One L2 block, with its logs and the market state at the block."""

  block_number: int
  """Block height."""
  batch_number: int | None
  """Number of the batch holding the block; `null` until the block is batched."""
  batch_status: (
    Literal['nothing_to_execute', 'committed', 'verified', 'executed'] | None
  )
  """L1 status of the batch; `null` until the batch reached L1."""
  batch_status_time: TimestampIso | None
  """When the batch reached `batch_status`; `null` alongside it."""
  batch_details: ExplorerBatchDetails | None
  """L1 transactions of the batch; `null` until committed."""
  total_transactions: int
  """Transactions in the block."""
  logs: list[ExplorerLog]
  """Logs of the block: only transactions that produced public data, not every transaction of the block."""
  markets: list[ExplorerMarketState]
  """State of every perp market at the block."""
